def can_reorder(n, a):
    total_sum = sum(a)
    if total_sum % 2 != 0:
        return -1

    target_sum = total_sum // 2
    a.sort()

    def find_partition(arr, start, end, current_sum, count):
        if count == n and current_sum == target_sum:
            return True
        if count == n or start > end:
            return False

        # Try including the current element in the partition
        if find_partition(arr, start + 1, end, current_sum + arr[start], count + 1):
            return True

        # Try excluding the current element from the partition
        if find_partition(arr, start + 1, end, current_sum, count):
            return True

        return False

    if find_partition(a, 0, len(a) - 1, 0, 0):
        return -1

    return ' '.join(map(str, a))

