def rearrange_array(n, a):
    a.sort()
    left_sum = sum(a[:n])
    right_sum = sum(a[n:])

    if left_sum == right_sum:
        for i in range(n):
            if a[i] < a[2*n-i-1]:
                a[i], a[2*n-i-1] = a[2*n-i-1], a[i]
                left_sum -= 2 * a[i]
                right_sum += 2 * a[i]
                if left_sum != right_sum:
                    return ' '.join(map(str, a))
        return '-1'
    else:
        return ' '.join(map(str, a))

